      const char *frag_name;
      int target_off, overlay_off;
      DTBLOB_T clone_dtb;
      int idx;

      node_name = fdt_get_name(overlay_dtb->fdt, frag_off, NULL);

      if (strncmp(node_name, "fragment@", 9) != 0 &&
          strncmp(node_name, "fragment-", 9) != 0)
         continue;

      frag_name = node_name + 9;

