      for (frag_off = fdt_first_subnode(overlay_dtb->fdt, 0), idx = 0;
           idx < frag_idx;
           frag_off = fdt_next_subnode(overlay_dtb->fdt, frag_off), idx++)
         continue;

      overlay_off = fdt_subnode_offset(overlay_dtb->fdt, frag_off, "__overlay__");
      if (overlay_off >= 0)
