      free(overlay_copy);

   if (err || !base_dtb)
      goto no_base_dtb;

   for (frag_off = fdt_first_subnode(overlay_dtb->fdt, 0), frag_idx = 0;
        frag_off >= 0;
        frag_off = fdt_next_subnode(overlay_dtb->fdt, frag_off), frag_idx++)
