static int dynstring_set_size(struct dynstring *ds, int size)
{
   if (size > ds->size)
   {
      size = (size * 5)/4; // Add a 25% headroom
      ds->buf = realloc(ds->buf, size);
      if (!ds->buf)
      {
         dtoverlay_error("  out of memory");
         return -FDT_ERR_NOSPACE;
      }
      ds->size = size;
   }
   else if (size < 0)
   {
      return -FDT_ERR_BADVALUE;
   }
   return 0;
}

